		extensionVersion: string;
		createdAt: number;
		// Live-trace landing zone (B1.3): the runtime channel from
		// strategy. Data ONLY — bounding/dedupe behavior lives in
		// MainOrchestrator.ingestTrace. Parsing the stream into
		// structure is a future design session (next-loop plan B1.4).
		// Generated .tactica types flatten this to Array<unknown>;
		// MainOrchestrator re-grounds it to traceEdge at the cast.
		traceBuffer: Array<{
			id: number;
			parentId: number | null;
			name: string;
			kind: string;
			status: string;
			duration: number | null;
			ts: number;
			instanceType: string | null;
			instanceSource?: 'explicit' | 'ambient' | null;
		}>;
		traceLastId: number;
		traceReceivedTotal: number;
		// Source session marker: pushers tag each ingest batch with the
		// target's identity (pid). A CHANGED marker means the source
		// process restarted — its edge ids restart from 1 and the
		// monotonic dedup would drop them all, so ingestTrace auto-wipes
		// first (VACUUM rule).
		traceSession: string | undefined;
		// The subsystem adapters the extension runs (navigation, strategy
		// server, self-trace), recorded as Main.Adapter instances by the
		// MainOrchestrator; state/query 'server' reports them. An Array,
		// not a Map — tactica's type printer drops Map type arguments
		adapters: Array<object>;
	}

